-- EatLog: everyday short names ("egg", "black coffee") for CoFID foods, so the
-- resolver's alias lookup finds them. CoFID's own names ("Eggs, chicken, whole,
-- boiled") never match what people say.
-- Generated by scripts/cofid/generate_aliases_migration.py from aliases.py — edit
-- those, not this file. Re-runnable: replaces all aliases on CoFID foods.

delete from public.food_aliases
where food_id in (select id from public.foods where source = 'cofid');

insert into public.food_aliases (food_id, alias)
